import{c as t,S as n,j as a,m as r}from"./chunks/framework.DjygN48H.js";const m=JSON.parse('{"title":"Versions and names","description":"","frontmatter":{},"headers":[],"relativePath":"learner/versions-and-names.md","filePath":"learner/versions-and-names.md"}'),o={name:"learner/versions-and-names.md"};function d(s,e,i,h,c,l){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="versions-and-names" tabindex="-1">Versions and names <a class="header-anchor" href="#versions-and-names" aria-label="Permalink to “Versions and names”">​</a></h1><h2 id="the-versions" tabindex="-1">The versions <a class="header-anchor" href="#the-versions" aria-label="Permalink to “The versions”">​</a></h2><p>A version keeps its name until the next one is named. 2019 and 2021 had a leadership team but <strong>no new version</strong>: Cadet carried on through 2019, and Knight through 2021.</p><table tabindex="0"><thead><tr><th>Version</th><th>Year</th><th>Main points</th></tr></thead><tbody><tr><td><strong>Spell</strong></td><td>2026</td><td>The current version. Language implementations run as Conductor evaluators, including Python (py2js, a Python CSE machine) and OCaml. Local-file imports for Python, search in the Python SICP book (SICPy), and a new login through NUS Entra ID. The old CAS and SAML logins, Sourcecast and Sourcereel, and the translations (i18n) were removed. The most active year in the history of the frontend.</td></tr><tr><td><strong>Charm</strong></td><td>2025</td><td>Frontend tooling moved to rsbuild and BlueprintJS v6. The old Concurrent and Interpreter paths were removed. A message channel to the VS Code extension. Structured logging in the backend.</td></tr><tr><td><strong>Strange</strong></td><td>2024</td><td>The frontend moved its state handling to Redux Toolkit, step by step (eight parts). SAML login in frontend and backend. A wrapper around the OpenAI API in the backend.</td></tr><tr><td><strong>Merlin</strong></td><td>2023</td><td>Release v1.5.0 (March 2023). Editing several files at once, Stories with search, search in SICP JS, and the environment visualizer extended with the agenda and the stash (the CSE machine). Typed variants of Source in the backend.</td></tr><tr><td><strong>Rook</strong></td><td>2022</td><td>A quiet year. The HTML chapter, the editor key-binding setting, and a long migration of the frontend to function components. Source versions in the backend.</td></tr><tr><td><strong>Knight</strong></td><td>2020 (and 2021)</td><td>Re-grading of submissions, GroundControl, the frontend can be disabled during an exam, and jQuery was removed. In 2021: the v2 backend API, courses for several institutions (multi-tenant, August 2021), login through Auth0, and a mobile navigation bar.</td></tr><tr><td><strong>Cadet</strong></td><td>2018 (and 2019)</td><td>The first version with this frontend and backend (the backend started in November 2017, the frontend in May 2018; release 1.0.0 in August 2018). Assessments, grading and XP, autograding on AWS Lambda, and Source §2. In 2019: notifications, Sourcecast and Sourcereel (recording and replaying a session), a maximum execution time, and the releases 1.4.0 and 1.4.1 (September 2019).</td></tr><tr><td><strong>Source Academy 2</strong></td><td>2017</td><td>Before the repositories described here.</td></tr><tr><td><strong>Source Academy</strong></td><td>2016</td><td>The original.</td></tr></tbody></table><h2 id="what-the-words-mean" tabindex="-1">What the words mean <a class="header-anchor" href="#what-the-words-mean" aria-label="Permalink to “What the words mean”">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Source Academy</strong></td><td>The whole system: what students and educators use, and everything behind it. This is the name to use in text.</td></tr><tr><td><strong>Spell</strong>, <strong>Charm</strong>, …</td><td>A version of the system, named by the team of that year. A version name is used only when a specific version is meant.</td></tr><tr><td><strong>Source</strong></td><td>The original name of the JavaScript sublanguages taught in the SICP JS book (Source §1 to §4). They are now called JavaScript §1 to §4. Not the same as Source Academy.</td></tr><tr><td><strong>slang</strong></td><td>A language implementation for Source Academy, named after its language: <code>js-slang</code>, <code>py-slang</code>, <code>ocaml-slang</code>, …</td></tr><tr><td><strong>Conductor</strong></td><td>The protocol and library through which the frontend (the host) runs a language implementation (an evaluator), which can live in a web worker or on a server.</td></tr><tr><td><strong>Evaluator</strong></td><td>A language implementation that speaks the Conductor protocol.</td></tr><tr><td><strong>Frontend</strong>, <strong>backend</strong></td><td>The web application in the browser, and the server with the database, the courses and the assessments.</td></tr><tr><td><strong>Grader</strong></td><td>The service that runs submitted programs against the tests of an assessment.</td></tr><tr><td><strong>Module</strong>, <strong>plugin</strong></td><td>A library of extra functions with optional user interface (the <code>modules</code> repository), and an extension of the frontend (the <code>plugins</code> repository).</td></tr></tbody></table><h2 id="historical-names-in-code" tabindex="-1">Historical names in code <a class="header-anchor" href="#historical-names-in-code" aria-label="Permalink to “Historical names in code”">​</a></h2><p><strong>Cadet</strong> is also the name of the backend&#39;s code. These identifiers keep the name. Renaming them would break deployed configuration and releases and help nobody, so they are not renamed:</p><ul><li>the Elixir application <code>:cadet</code> and the <code>Cadet.*</code> modules, and the Mix tasks such as <code>mix cadet.token</code>;</li><li>the backend configuration file <code>cadet.exs</code> (<code>/etc/cadet.exs</code> on a server);</li><li>the frontend&#39;s old repository name <code>cadet-frontend</code>, which GitHub redirects, and the Sentry project of the same name;</li><li>the <code>--cadet-color-*</code> CSS variables in the frontend;</li><li>the title of the backend&#39;s API description.</li></ul><p>If you read &quot;cadet&quot; in code or in an old document, it means the Source Academy backend (or the whole system, as it was in 2018).</p><h2 id="how-a-version-gets-its-name" tabindex="-1">How a version gets its name <a class="header-anchor" href="#how-a-version-gets-its-name" aria-label="Permalink to “How a version gets its name”">​</a></h2><p>The name is chosen by Martin Henz. Recently the core team has made suggestions, and the best one, as judged by Martin Henz, has won a coffee.</p><p>When a name is chosen, add a row for it to the table above: this page is where the versions and their years are recorded. (The <a href="https://sourceacademy.org/contributors" target="_blank" rel="noreferrer">contributors page</a> of the frontend still lists them in its own text.)</p>',13)])])}const u=t(o,[["render",d]]);export{m as __pageData,u as default};
